diff --git a/lib/matching/__tests__/write-paths-parity.test.ts b/lib/matching/__tests__/write-paths-parity.test.ts
new file mode 100644
index 00000000..85f4767c
--- /dev/null
+++ b/lib/matching/__tests__/write-paths-parity.test.ts
@@ -0,0 +1,318 @@
+/**
+ * Parity test — write paths convergence (B.2)
+ *
+ * Both write paths must produce the same values for the 21 canonical columns
+ * when given the same cargo/vessel pair:
+ *
+ *   computeAndPersistMatches (background precompute, compute-matches.ts)
+ *   persistSessionMatches    (on-render per-session persist, persist-session-matches.ts)
+ *
+ * Columns compared: cargo_id, vessel_id, cargo_type, load_port, discharge_port,
+ * laycan_start, laycan_end, vessel_dwt, tce_usd_per_day, distance_nm,
+ * freight_rate_usd_per_mt, freight_rate_source, vessel_name, cargo_ref,
+ * fit_percent, cargo_item_index, vessel_item_index, consumption_estimated,
+ * ballast_distance_nm, breakeven_tce_usd_per_day,
+ * plus worksheet_json presence and fit_breakdown presence.
+ *
+ * analyzePairs is mocked to return a deterministic Match with full fields
+ * (fitBreakdown, fitPercent, worksheet, economics, itemIndices) so both paths
+ * receive identical engine output and should converge on the DB columns.
+ */
+
+import Database from 'better-sqlite3';
+import migration032 from '@/lib/migrations/032-matches';
+import migration033 from '@/lib/migrations/033-matches-score-breakdown';
+import migration034 from '@/lib/migrations/034-matches-unique-constraint';
+import migration035 from '@/lib/migrations/035-matches-tce-distance';
+import migration036 from '@/lib/migrations/036-matches-freight-rate';
+import migration041 from '@/lib/migrations/041-matches-vessel-name';
+import migration042 from '@/lib/migrations/042-matches-fit';
+import migration044 from '@/lib/migrations/044-matches-item-index';
+import migration045 from '@/lib/migrations/045-matches-worksheet';
+import migration046 from '@/lib/migrations/046-matches-consumption-estimated';
+import migration047 from '@/lib/migrations/047-matches-ballast-distance';
+import migration050 from '@/lib/migrations/050-matches-breakeven';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, Match, FitBreakdown } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_ID = 'parity-cargo-1';
+const VESSEL_ID = 'parity-vessel-1';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  migration032.up(db);
+  migration033.up(db);
+  migration034.up(db);
+  migration035.up(db);
+  migration036.up(db);
+  migration041.up(db);
+  migration042.up(db);
+  migration044.up(db);
+  migration045.up(db);
+  migration046.up(db);
+  migration047.up(db);
+  migration050.up(db);
+  return db;
+}
+
+function makeCargo(): ParsedCargo {
+  return {
+    emailId: CARGO_ID,
+    itemIndex: 0,
+    originPort: { value: 'Rotterdam', confidence: 'confirmed' },
+    destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+    cargoType: 'GRAIN',
+    laycan: '1-15 Jul 2025',
+    weightMt: { value: 50000, confidence: 'confirmed' },
+    cargoDescription: { value: 'Wheat bulk', confidence: 'confirmed' },
+    weightMtMin: null, weightMtMax: null, volumeCbm: null, dimensions: null,
+    containerType: null, quantity: null, incoterms: null, preferredDates: null,
+    loadingRate: null, dischargeRate: null, commissionPercent: null,
+    commissionTerms: null, specialRequirements: null, stowageFactor: null,
+    missingInfo: [], originCountry: null, destinationCountry: null,
+  };
+}
+
+function makeVessel(): ParsedVessel {
+  return {
+    emailId: VESSEL_ID,
+    itemIndex: 0,
+    dwtSummer: { value: 75000, confidence: 'confirmed' },
+    vesselName: { value: 'MV PARITY TEST', confidence: 'confirmed' },
+    openDate: { value: '2025-06-20', confidence: 'confirmed' },
+    openPosition: { value: 'Rotterdam', confidence: 'confirmed' },
+    speedLaden: '13 kts',
+    consumption: '28 mt/day',
+    imo: null, flag: null, built: null, classSociety: null, pandi: null,
+    dwcc: null, draftMax: null, loa: null, beam: null, grt: null, nrt: null,
+    holdsCount: null, hatchesCount: null, grainCapacity: null,
+    grainCapacityUnit: null, baleCapacity: null, holdDimensions: null,
+    hatchDimensions: null, tankTopStrength: null, geared: null,
+    craneCapacity: null, hatchType: null, vesselType: null,
+    direction: null, restrictions: [], lastCargoes: null, speedBallast: null,
+    deckCapacity: null, specialFeatures: [],
+  };
+}
+
+const MOCK_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Utilisation', weight: 15, score: 12, rationale: 'Good' },
+    { factor: 'timing', label: 'Timing', weight: 20, score: 18, rationale: 'Ideal' },
+    { factor: 'economics', label: 'Economics', weight: 15, score: 13, rationale: 'Viable' },
+  ],
+  totalWeight: 50,
+  fitPercent: 86,
+  partCargo: false,
+  vesselClass: 'panamax',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: { distanceNm: 15000, gapDays: 5, verdict: 'ideal', utilisation: 0.72, vesselDwt: 75000, cargoWtMax: 50000 },
+};
+
+function makeMockMatch(): Match {
+  return {
+    cargoEmailId: CARGO_ID,
+    cargoItemIndex: 0,
+    vesselEmailId: VESSEL_ID,
+    vesselItemIndex: 0,
+    score: 82,
+    matchLevel: 'good',
+    matchReasons: ['Good DWT fit'],
+    issues: [],
+    fitPercent: 86,
+    fitBreakdown: MOCK_FIT_BREAKDOWN,
+    scoreBreakdown: null,
+    worksheet: {
+      readiness: {
+        openDate: '2025-06-20',
+        laycanStart: '2025-07-01',
+        laycanEnd: '2025-07-15',
+        distanceNm: 15000,
+        distanceExact: true,
+        speedKn: 13,
+        sailingDays: 48.1,
+        arrivalDate: '2025-08-07',
+        gapDays: null,
+        verdict: 'idle',
+        explanation: 'idle',
+        openPosition: 'Rotterdam',
+      },
+      vessel: {
+        draftMax: null, grainCapacity: null, grainCapacityUnit: null,
+        geared: null, vesselType: null, flag: null, built: null,
+        pandi: null, classSociety: null, lastCargoes: null,
+        dwtSummer: 75000, dwcc: null,
+      },
+      cargo: {
+        weightMt: 50000, weightMtEffective: 50000,
+        cargoType: 'GRAIN', loadPort: 'Rotterdam', dischargePort: 'Singapore',
+      },
+      hardFilters: { draft: { pass: true }, crane: { pass: true }, volume: { pass: true }, cargoVessel: { pass: true }, destDraft: { pass: true }, destCrane: { pass: true }, cargoWeight: { pass: true } },
+    },
+    hardFilters: undefined,
+    sanctions: undefined,
+    economics: {
+      tceUsdPerDay: 12500,
+      freightRateUsdPerMt: 28,
+      freightRateSource: 'baltic-tier2',
+      breakdown: {
+        bunkerCost: 280000, bunkerPort: 'NLRTM', euEtsAmount: 15000,
+        euEtsApplicable: true, warRiskPremium: 0, warRiskZones: [],
+      },
+      totalUsd: 320000,
+      calculatedAt: '2025-06-10T00:00:00.000Z',
+      dataFreshness: { bunker: '2025-06-10', eua: '2025-06-10' },
+    },
+  };
+}
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-paths-parity — computeAndPersistMatches vs persistSessionMatches', () => {
+  it('both paths write identical values for the 21 canonical columns', async () => {
+    const dbA = freshDb(); // computeAndPersistMatches
+    const dbB = freshDb(); // persistSessionMatches
+
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const mockMatch = makeMockMatch();
+
+    // Path A: background precompute
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [mockMatch],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-A', dbA);
+
+    // Path B: on-render session persist
+    persistSessionMatches(dbB, 'session-B', [mockMatch], [cargo], [vessel]);
+
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+
+    expect(rowA).toBeDefined();
+    expect(rowB).toBeDefined();
+
+    // Identity columns
+    expect(rowA.cargo_id).toBe(rowB.cargo_id);
+    expect(rowA.vessel_id).toBe(rowB.vessel_id);
+    expect(rowA.cargo_type).toBe(rowB.cargo_type);
+    expect(rowA.load_port).toBe(rowB.load_port);
+    expect(rowA.discharge_port).toBe(rowB.discharge_port);
+    expect(rowA.laycan_start).toBe(rowB.laycan_start);
+    expect(rowA.laycan_end).toBe(rowB.laycan_end);
+    expect(rowA.vessel_dwt).toBe(rowB.vessel_dwt);
+    expect(rowA.vessel_name).toBe(rowB.vessel_name);
+    expect(rowA.cargo_ref).toBe(rowB.cargo_ref);
+
+    // Item-index columns (B.2)
+    expect(rowA.cargo_item_index).toBe(rowB.cargo_item_index);
+    expect(rowA.vessel_item_index).toBe(rowB.vessel_item_index);
+
+    // Fit columns (B.2)
+    expect(rowA.fit_percent).toBe(rowB.fit_percent);
+    expect(rowA.fit_breakdown).not.toBeNull();
+    expect(rowB.fit_breakdown).not.toBeNull();
+
+    // Economics columns — both paths use computeStoredMatchEconomics on the same inputs
+    expect(rowA.tce_usd_per_day).not.toBeNull();
+    expect(rowA.tce_usd_per_day).toBe(rowB.tce_usd_per_day);
+    expect(rowA.distance_nm).toBe(rowB.distance_nm);
+    expect(rowA.freight_rate_usd_per_mt).toBe(rowB.freight_rate_usd_per_mt);
+    expect(rowA.freight_rate_source).toBe(rowB.freight_rate_source);
+
+    // New columns (B.2)
+    expect(rowA.consumption_estimated).toBe(rowB.consumption_estimated);
+    expect(rowA.ballast_distance_nm).toBe(rowB.ballast_distance_nm);
+    expect(rowA.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(rowA.breakeven_tce_usd_per_day).toBe(rowB.breakeven_tce_usd_per_day);
+
+    // Worksheet presence (B.2)
+    expect(rowA.worksheet_json).not.toBeNull();
+    expect(rowB.worksheet_json).not.toBeNull();
+  });
+
+  it('fit_breakdown is non-null in both paths when Match.fitBreakdown is set', async () => {
+    const dbA = freshDb();
+    const dbB = freshDb();
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const mockMatch = makeMockMatch();
+
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [mockMatch],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-fb-A', dbA);
+    persistSessionMatches(dbB, 'session-fb-B', [mockMatch], [cargo], [vessel]);
+
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+
+    expect(JSON.parse(rowA.fit_breakdown!)).toMatchObject({ fitPercent: 86 });
+    expect(JSON.parse(rowB.fit_breakdown!)).toMatchObject({ fitPercent: expect.any(Number) });
+  });
+
+  it('worksheet_json is non-null in both paths when Match.worksheet is set', async () => {
+    const dbA = freshDb();
+    const dbB = freshDb();
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const mockMatch = makeMockMatch();
+
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [mockMatch],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-ws-A', dbA);
+    persistSessionMatches(dbB, 'session-ws-B', [mockMatch], [cargo], [vessel]);
+
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+
+    const wsA = JSON.parse(rowA.worksheet_json!);
+    const wsB = JSON.parse(rowB.worksheet_json!);
+    expect(wsA.readiness.verdict).toBe('idle');
+    expect(wsB.readiness.verdict).toBe('idle');
+  });
+
+  it('breakeven_tce_usd_per_day is set for known-DWT vessels in both paths', async () => {
+    const dbA = freshDb();
+    const dbB = freshDb();
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const mockMatch = makeMockMatch();
+
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [mockMatch],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-bev-A', dbA);
+    persistSessionMatches(dbB, 'session-bev-B', [mockMatch], [cargo], [vessel]);
+
+    const [rowA] = listMatches(dbA, { sortBy: 'score', sortDir: 'desc' });
+    const [rowB] = listMatches(dbB, { sortBy: 'score', sortDir: 'desc' });
+
+    expect(typeof rowA.breakeven_tce_usd_per_day).toBe('number');
+    expect(typeof rowB.breakeven_tce_usd_per_day).toBe('number');
+    expect(rowA.breakeven_tce_usd_per_day).toBe(rowB.breakeven_tce_usd_per_day);
+  });
+});
