+      laycanEnd: '2026-07-15',
+      distanceNm: 15300,
+      distanceExact: true,
+      speedKn: 13,
+      sailingDays: 49,
+      arrivalDate: '2026-07-01',
+      gapDays: 5,
+      verdict: 'ideal',
+      explanation: 'Vessel arrives within laycan window',
+    },
+    hardFilters: {
+      draft: { pass: true },
+      crane: { pass: true },
+      volume: { pass: true },
+      cargoVessel: { pass: true },
+      destDraft: { pass: true },
+      destCrane: { pass: true },
+      cargoWeight: { pass: true },
+    },
+    sanctions: { risk: 'LOW', blocking: false },
+  };
+}
+
+function makeMatchWithWorksheet(): Match {
+  const m = makeMatch();
+  const worksheet: MatchWorksheet = {
+    readiness: {
+      ...m.readiness!,
+      openPosition: 'Rotterdam',
+    },
+    vessel: {
+      draftMax: 12.5,
+      grainCapacity: 70000,
+      grainCapacityUnit: 'cbm',
+      geared: false,
+      vesselType: 'BULK CARRIER',
+      flag: 'PAN',
+      built: 2012,
+      pandi: null,
+      classSociety: 'BV',
+      lastCargoes: 'GRAIN, SOYBEANS',
+      dwtSummer: 57000,
+      dwcc: 55000,
